pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function _accessControlId() internal pure returns (bytes4) {
        bytes4 hasRole = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 getRoleAdmin = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 grantRole = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 revokeRole = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 renounceRole = bytes4(keccak256("renounceRole(bytes32,address)"));
        return hasRole ^ getRoleAdmin ^ grantRole ^ revokeRole ^ renounceRole;
    }

    function testFuzz_property(uint256 whichInterface) public {
        // The admissible domain: the set of interfaces the protocol inherits and must advertise.
        // `whichInterface` indexes this set, so the fuzzer controls which interface id is queried.
        uint256 idx = bound(whichInterface, 0, 1);
        bytes4[] memory ids = new bytes4[](2);
        ids[0] = type(IERC165).interfaceId;
        ids[1] = _accessControlId();

        bytes4 queried = ids[idx];
        assertTrue(c.supportsInterface(queried));
    }
}

