pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    bytes4 constant ERC165_ID = type(IERC165).interfaceId;

    function setUp() public { c = new C(); }

    function testFuzz_property(bytes4 queriedId) public {
        // Compose the IAccessControl interface id at runtime from its role-management selectors
        bytes4 hasRoleSel = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 getRoleAdminSel = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 grantRoleSel = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 revokeRoleSel = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 renounceRoleSel = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 accessControlId = hasRoleSel ^ getRoleAdminSel ^ grantRoleSel ^ revokeRoleSel ^ renounceRoleSel;

        bool supported = c.supportsInterface(queriedId);
        bool expected = (queriedId == ERC165_ID) || (queriedId == accessControlId);

        assertTrue(supported == expected);
    }
}

