pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes4 selector) public {
        // Compute the AccessControl interface id at runtime from its five
        // role-management function signatures, without referencing any
        // local interface/event declarations (avoids shadowing).
        bytes4 idHasRole = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 idGetRoleAdmin = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 idGrantRole = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 idRevokeRole = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 idRenounceRole = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 accessControlId = idHasRole ^ idGetRoleAdmin ^ idGrantRole ^ idRevokeRole ^ idRenounceRole;

        bytes4 erc165Id = 0x01ffc9a7;

        bool supported = c.supportsInterface(selector);

        // General rule: for EVERY queried selector, the contract reports
        // support exactly when the selector is the ERC165 id or the
        // (dynamically computed) AccessControl id. The buggy version drops
        // the AccessControl branch and returns false for accessControlId.
        assertTrue(
            supported == (selector == erc165Id || selector == accessControlId),
            "supportsInterface must recognize ERC165 and AccessControl ids"
        );
    }
}

