pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes4 interfaceId) public {
        // admissible domain: any interfaceId that is NOT one of the two interface ids
        // explicitly supported by the reference implementation (IERC165, IAccessControl)
        vm.assume(interfaceId != type(IERC165).interfaceId);
        vm.assume(interfaceId != 0x7965db0b); // type(IAccessControl).interfaceId

        bool ok = c.supportsInterface(interfaceId);
        // general rule: an unrelated interfaceId is NOT supported
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Choose an interfaceId from the whole input space, but make sure the fuzzer
        // explores both supported and unsupported interface ids.
        bytes4 ierc165Id = type(IERC165).interfaceId;
        bytes4 iacId = type(IAccessControl).interfaceId;

        uint256 choice = bound(seed, 0, 2);
        bytes4 interfaceId;
        if (choice == 0) {
            interfaceId = ierc165Id;
        } else if (choice == 1) {
            interfaceId = iacId;
        } else {
            // Arbitrary bytes4 derived from the fuzz seed (covers unsupported space widely)
            interfaceId = bytes4(uint32(uint256(keccak256(abi.encodePacked(seed)))));
        }

        bool expected = (interfaceId == ierc165Id || interfaceId == iacId);

        bool ok = true;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            ok = supported;
        } catch {
            ok = false;
        }

        // General rule: for ANY interfaceId, supportsInterface completes and returns
        // true exactly for IERC165 / IAccessControl ids, false otherwise.
        assertTrue(ok == expected);
    }
}

