pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // The fuzzer searches the full interface-id space; for any admissible id,
        // the reference contract answers `true` iff the id is one of the two
        // registered interface ids, and never reverts.
        bytes4 iid = bytes4(seed);

        bool ok = true;
        try c.supportsInterface(iid) returns (bool supported) {
            ok = supported;
        } catch {
            ok = true; // reference never reverts; treat a revert as a violation marker
        }

        bool expected = (iid == bytes4(0x01ffc9a7)) // IERC165.interfaceId
            || (iid == bytes4(0x7965db0b)); // IAccessControl.interfaceId

        assertTrue(ok == expected);
    }
}
